public static class SeedData { public static async Task SeedAsync(LacDbContext db, CancellationToken ct) { if(await db.Districts.AnyAsync(ct)) return; var d=new District{Name="South West Delhi"}; var s=new SubDivision{District=d,Name="Demo Sub-Division"}; var v=new Village{SubDivision=s,Name="Galibpur"}; var p=new AcquisitionProject{Name="Demo Corridor Acquisition",RequiringAgency="Demo Requiring Agency",ActRegime="Land Acquisition Act (demo)"}; var k1=new Khasra{Village=v,DisplayNumber="22//1",NormalizedNumber=KhasraNumber.Normalize("22//1"),TotalArea=4.0000m,AreaUnit="Bigha"}; var k2=new Khasra{Village=v,DisplayNumber="22//2",NormalizedNumber=KhasraNumber.Normalize("22//2"),TotalArea=3.5000m,AreaUnit="Bigha"}; var k3=new Khasra{Village=v,DisplayNumber="22//1/6",NormalizedNumber=KhasraNumber.Normalize("22//1/6"),TotalArea=1.2500m,AreaUnit="Bigha"}; var n4=new Notification{AcquisitionProject=p,SectionType="4",NotificationNumber="DEMO-S4-2026-001",NotificationDate=new DateOnly(2026,1,12)}; var n6=new Notification{AcquisitionProject=p,SectionType="6",NotificationNumber="DEMO-S6-2026-001",NotificationDate=new DateOnly(2026,3,4)}; var a=new Award{AcquisitionProject=p,AwardNumber="DEMO-AWARD-01",AwardDate=new DateOnly(2026,6,1),AwardType="Demo",Status="Published"}; db.AddRange(d,s,v,p,k1,k2,k3,n4,n6,a,new NotificationKhasra{Notification=n4,Khasra=k2,NotifiedArea=2m,AreaUnit="Bigha"},new NotificationKhasra{Notification=n6,Khasra=k2,NotifiedArea=2m,AreaUnit="Bigha"},new AwardKhasra{Award=a,Khasra=k2,AcquiredArea=2m,AreaUnit="Bigha",AcquisitionStatus="Acquired"},new AwardKhasra{Award=a,Khasra=k3,AcquiredArea=1.25m,AreaUnit="Bigha",AcquisitionStatus="Acquired"}); var lr=new VillageLR{Village=v,RegisterReference="DEMO-LR-GAL-01"}; db.Add(lr); db.Add(new LREntry{VillageLR=lr,RowNumber=1,RawKhasraText="22//2 min",Khasra=k2,RawAreaText="2 bigha",ParsedArea=2m,AreaUnit="Bigha",Section4NotificationId=n4.Id,Section6NotificationId=n6.Id,AwardId=a.Id,RawRemarks="Dummy training data",VerificationStatus=VerificationStatus.Verified}); await db.SaveChangesAsync(ct); } }
